public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> currentPermutation = new ArrayList<>();
    backtrack(nums, used, currentPermutation, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> currentPermutation, List<List<Integer>> result) {
    if (currentPermutation.size() == nums.length) {
        result.add(new ArrayList<>(currentPermutation));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        currentPermutation.add(nums[i]);
        backtrack(nums, used, currentPermutation, result);
        used[i] = false;
        currentPermutation.remove(currentPermutation.size() - 1);
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        for (int start = 0; start <= strings.get(0).length() - length; start++) {
            String substring = strings.get(0).substring(start, start + length);
            String inverseSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(inverseSubstring)) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                maxLength = length;
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int oilDeposits = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                oilDeposits++;
                dfs(grid, visited, i, j);
            }
        }
    }

    return oilDeposits;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int i = 0; i < 8; i++) {
        int newRow = row + rowDirections[i];
        int newCol = col + colDirections[i];

        if (isValid(grid, visited, newRow, newCol)) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

private static boolean isValid(char[][] grid, boolean[][] visited, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length && grid[row][col] == '@' && !visited[row][col];
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The maximum number of regions formed by N triangles can be calculated using the formula:
    // R(N) = 2 + 7N - 3N^2/2 + N^3/6
    // This formula is derived from the fact that each new triangle can intersect all previous triangles
    // in 6 new points, creating 7 new regions minus the 3 regions it overlaps with.
    // Simplified to R(N) = 2 + 3N^2/2 - N^3/6
    // Further simplified to R(N) = 2 + N * (3N - N^2) / 2 for integer arithmetic
    return 2 + N * (3 * N - N * N) / 2;
}

