public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    // Initialize the adjacency list
    boolean[][] connected = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) continue;
        int from = path[0];
        int to = path[1];
        if (from >= 0 && from < n && to >= 0 && to < n) {
            connected[from][to] = true;
            connected[to][from] = true; // Assuming bidirectional paths
        }
    }

    // BFS to check if there is a path from start to end
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0]);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int next = 0; next < n; next++) {
            if (connected[current][next] && !visited[next]) {
                queue.offer(next);
                visited[next] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Invalid input";
    }

    int commonCount = 0;
    int lengthSum = word1.length() + word2.length();

    boolean[] used = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word2.charAt(j) == c1) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    if (lengthSum == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonCount, lengthSum);
    int numerator = commonCount / gcd;
    int denominator = lengthSum / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (denominator == 1 ? numerator : numerator + "/" + denominator);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

