public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int allOne = (1 << k) - 1;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        // Add the current bit to the value
        value = (value << 1) & allOne | (s.charAt(i) - '0');

        // Only add to the set once we have a substring of length k
        if (i >= k - 1) {
            seen.add(value);
        }
    }

    return seen.size() == 1 << k;
}

