public int minInsertions(String s) {
    int open = 0; // tracks the number of unmatched '('
    int insertions = 0; // tracks the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // we encountered a ')'
            if (open > 0) {
                open--; // match it with an existing '('
            } else {
                insertions++; // need to insert a '(' to match this ')'
            }

            // check if we need to handle an unpaired ')'
            // since every closing needs a pair, if next is not ')', insert one
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // skip the next ')', as its pair is already handled
            } else {
                insertions++; // need to insert a ')' to pair this current ')'
            }
        }
    }

    // any remaining '(' need a ')'
    insertions += open * 2;

    return insertions;
}

public int minOperations(int n) {
    // The target value for all elements to be equal
    int target = n;
    int operations = 0;

    // Calculate the number of operations needed
    for (int i = 0; i < n / 2; i++) {
        int currentValue = (2 * i) + 1;
        operations += target - currentValue;
    }

    return operations;
}

