}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high / 10) continue;

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be a non-negative integer.");
    }

    int count = 0;
    long factor = 1;
    int lowerNum = 0, curNum = 0, higherNum = 0;

    while (n / factor != 0) {
        lowerNum = (int)(n - (n / factor) * factor);
        curNum = (int)((n / factor) % 10);
        higherNum = (int)(n / (factor * 10));

        if (curNum == 0) {
            count += higherNum * factor;
        } else if (curNum == 1) {
            count += higherNum * factor + lowerNum + 1;
        } else {
            count += (higherNum + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

