    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                if (j == 0) {
                    horizontal[i][j] = 1;
                } else {
                    horizontal[i][j] = horizontal[i][j - 1] + 1;
                }

                // Vertical
                if (i == 0) {
                    vertical[i][j] = 1;
                } else {
                    vertical[i][j] = vertical[i - 1][j] + 1;
                }

                // Diagonal
                if (i == 0 || j == 0) {
                    diagonal[i][j] = 1;
                } else {
                    diagonal[i][j] = diagonal[i - 1][j - 1] + 1;
                }

                // Anti-diagonal
                if (i == 0 || j == cols - 1) {
                    antiDiagonal[i][j] = 1;
                } else {
                    antiDiagonal[i][j] = antiDiagonal[i - 1][j + 1] + 1;
                }

                // Update the maximum length found
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        result.append(n % 10);
        n /= 10;
        count++;

        if (count % 3 == 0 && n != 0) {
            result.append('.');
        }
    }

    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new ArrayList<>(), count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, int[] count) {
    if (current.size() == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) {
            continue;
        }

        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
            current.add(A[i]);
            backtrack(A, used, current, count);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;

    int i = 0;
    while (i < n) {
        if (top == -1 || heights[i] >= heights[stack[top]]) {
            stack[++top] = i++;
        } else {
            int h = heights[stack[top--]];
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, h * (i - left - 1));
        }
    }

    while (top != -1) {
        int h = heights[stack[top--]];
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, h * (n - left - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) { // moving up
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // moving down
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after i in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of any overflow, though the problem constraints should prevent this
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
    }

    return centerSymmetricNumbersHelper(n, n);
}

private static List<String> centerSymmetricNumbersHelper(int currentLength, int targetLength) {
    if (currentLength == 0) return new ArrayList<>(List.of(""));
    if (currentLength == 1) return new ArrayList<>(List.of("0", "1", "8"));

    List<String> subResults = centerSymmetricNumbersHelper(currentLength - 2, targetLength);
    List<String> results = new ArrayList<>();

    for (String s : subResults) {
        if (currentLength != targetLength) {
            results.add("0" + s + "0");
        }
        results.add("1" + s + "1");
        results.add("6" + s + "9");
        results.add("8" + s + "8");
        results.add("9" + s + "6");
    }

    return results;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be an array of 3 points, each with 2 coordinates.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points using the determinant method
    // Area = 0.5 * | x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) |
    // If the area is 0, the points are collinear and do not form a boomerang
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The order must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }
    int uniqueSum = 0;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }
    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Create a dp array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Initialize the dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Base case: 0 can be represented by 0 numbers
    dp[0] = 0;

    // Precompute all perfect squares less than or equal to n
    int maxSquareIndex = (int) Math.sqrt(n);
    int[] squares = new int[maxSquareIndex + 1];
    for (int i = 1; i <= maxSquareIndex; i++) {
        squares[i] = i * i;
    }

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= maxSquareIndex && squares[j] <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - squares[j]] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        result.append(reversedWord.reverse().toString()).append(" ");
    }

    // Remove the trailing space
    return result.toString().trim();
}
